Three phenomena stood out.
\begin{itemize}
\item \emph{Plateau.} Every row is flat to within $5.3\%$, and the abelian rows to within $1.6\%$ on the experiment's summary statistic. For the abelian batteries the empirical residual entropy $H(L\mid P)$ was exactly $0$ at every size.
\item \emph{Pool-floor exception.} At $k=10$ the $S_3$ battery read $0.7423$. The pool contained only $75$ primes, about $2.5$ per class mod $31$.
\item \emph{Which-factor wall.} The conditional orientation-permutation test held in all $16$ cells, with $\max|z|=1.55$. The naive unconditional test would have signalled violation at up to $|z|=4.7$.
\end{itemize}

\subsection{Summary of the method}
Mutual information on a finite uniform population is an average of a log-ratio of counts. Maps with uniform fibres rescale all counts by the same factor and leave this average unchanged. This observation shows that size changes nothing (Section~\ref{sec:size}), and that the residue space can be replaced by a tiny dial box (Section~\ref{sec:lift}), which makes the plateaus computable (Section~\ref{sec:plateaus}). A two-term decomposition explains the pool floor (Section~\ref{sec:pool}), and a pairing argument proves the wall (Section~\ref{sec:wall}).

\section{Definitions and the pointwise form}

Throughout, $\Omega$ is a finite nonempty set with the uniform probability measure. A \emph{read-out} is a function $X:\Omega\to\mathcal X$. Write $n_X(\omega)=\#\{\omega':X(\omega')=X(\omega)\}$ and $n_{X,Y}(\omega)=\#\{\omega':X(\omega')=X(\omega),\,Y(\omega')=Y(\omega)\}$.

\begin{definition}[Entropies]
$H(X)=-|\Omega|^{-1}\sum_{\omega}\log_2\bigl(n_X(\omega)/|\Omega|\bigr)$. The conditional entropy $H(X\mid Y)$ is the average over the fibres $Y^{-1}(y)$, weighted by fibre size, of the entropy of $X$ restricted to the fibre. The mutual information is $I(X;Y)=H(X)-H(X\mid Y)$.
\end{definition}

On an empirical sample these are the plug-in estimators. On a population they are the exact Shannon quantities.

\begin{definition}[Battery, hint value]
A \emph{battery} is $(\Omega,L,P,N)$ with label $L$, pair view $P$ and product view $N$. Its hint value is $\Hint(L,P,N)=I(L;P)-I(L;N)$, and its \emph{residual} is $H(L\mid P)$.
\end{definition}

\begin{proposition}[Pointwise form]\label{prop:pointwise}
For read-outs $X,Y$ on $\Omega$,
\[
I(X;Y)=\frac1{|\Omega|}\sum_{\omega\in\Omega}\log_2\frac{|\Omega|\,n_{X,Y}(\omega)}{n_X(\omega)\,n_Y(\omega)}.
\]
\end{proposition}
\begin{proof}[Proof sketch]
Expand $I$ as a double sum over joint cells. Split the sum over $\omega$ fibrewise by $Y$ and then $X$. The summand is constant on each joint cell, and all counts are positive at sample points, so the logarithm splits into four terms. Summing over a cell gives the cell count times the log-ratio.
\end{proof}

In particular $H(X\mid X)=0$, so $H(X)=I(X;X)$.

\section{Uniform-fibre transport and size-stability}\label{sec:size}

\begin{lemma}[Uniform fibres]\label{lem:fibres}
Let $f:\Omega\to\Omega'$ have $|f^{-1}(y)|=K$ for all $y$. Then $|\Omega|=K|\Omega'|$. For every predicate $Q$ on $\Omega'$, $\#\{\omega:Q(f\omega)\}=K\#\{y:Q(y)\}$. For every $F:\Omega'\to\mathbb R$, $\sum_\omega F(f\omega)=K\sum_yF(y)$.
\end{lemma}
\begin{proof}
Partition $\Omega$ into fibres of $f$.
\end{proof}

\begin{theorem}[Uniform-fibre transport]\label{thm:transport}
Let $f:\Omega\to\Omega'$ have all fibres of size $K>0$, let $X,Y$ be read-outs on $\Omega$ and $X',Y'$ read-outs on $\Omega'$. Suppose that for all $\omega$
\[
\frac{|\Omega|\,n_{X,Y}(\omega)}{n_X(\omega)n_Y(\omega)}=\frac{|\Omega'|\,n_{X',Y'}(f\omega)}{n_{X'}(f\omega)n_{Y'}(f\omega)}.
\]
Then $I(X;Y)=I(X';Y')$.
\end{theorem}
\begin{proof}[Proof sketch]
By Proposition~\ref{prop:pointwise} the pointwise densities satisfy $i(\omega)=i'(f\omega)$. By Lemma~\ref{lem:fibres}, $\sum_\omega i(\omega)=K\sum_y i'(y)$ and $|\Omega|=K|\Omega'|$. The factor $K$ cancels.
\end{proof}

\begin{corollary}[Entropy transport]\label{cor:enttransport}
If $f$ has uniform fibres, then $H(X'\circ f)=H(X')$.
\end{corollary}

\begin{theorem}[Size-stability]\label{thm:size}
Let $(\Omega,L,P,N)$ be a battery and $F$ a finite nonempty set. Define $\tilde L(\omega,j)=L(\omega)$ on $\Omega\times F$, and similarly $\tilde P$ and $\tilde N$. Then $I(\tilde L;\tilde P)=I(L;P)$ and $\Hint(\tilde L,\tilde P,\tilde N)=\Hint(L,P,N)$.
\end{theorem}
\begin{proof}
The projection $\Omega\times F\to\Omega$ has fibres of size $|F|$. All counts scale by $|F|$, so the ratios agree. Apply Theorem~\ref{thm:transport}.
\end{proof}

\begin{remark}
The hint value is a functional of the class-level law alone; there is no size law to find. Observed drift can only come from estimator bias or from departures of the real pool from the class law.
\end{remark}

\section{The residue-lift theorem}\label{sec:lift}

Let $G$ be a finite abelian group (e.g.\ $(\Z/m)^\times$), $\psi:G\to H$ a surjective homomorphism (the \emph{dial}), $C$ a finite coin set and $\ell:H\times H\times C\to\Lambda$. The \emph{residue space} is $\Omega_G=(G\times G)\times C$, with $L_G(a,b,c)=\ell(\psi a,\psi b,c)$, $P(a,b,c)=(a,b)$ and $N(a,b,c)=ab$. The \emph{dial box} is $\Omega_H=(H\times H)\times C$, with the same label, $P_H=(h_1,h_2)$ and $N_H=h_1h_2$. The \emph{dial map} is $\delta(a,b,c)=(\psi a,\psi b,c)$. The uniform law on $\Omega_G$ is the Dirichlet--Chebotarev population model. Let $\kappa=|\ker\psi|$.

\begin{lemma}[Dial fibres]\label{lem:dialfibres}
Every fibre of $\psi$ has $\kappa$ elements, so $|G|=\kappa|H|$, and every fibre of $\delta$ has $\kappa^2$ elements.
\end{lemma}

\begin{lemma}[Factorisation count]\label{lem:factor}
If $h_1h_2=\psi(n)$, then $\#\{(a,b):ab=n,\ \psi a=h_1,\ \psi b=h_2\}=\kappa$.
\end{lemma}
\begin{proof}
The map $(a,b)\mapsto a$ is a bijection onto $\psi^{-1}(h_1)$ with inverse $a\mapsto(a,a^{-1}n)$. The condition $\psi(a^{-1}n)=h_2$ is automatic.
\end{proof}

\begin{theorem}[Residue lift]\label{thm:lift}
$I(L_G;P)=I(L_H;P_H)$ and $I(L_G;N)=I(L_H;N_H)$. Hence $\Hint(L_G,P,N)=\Hint(L_H,P_H,N_H)$.
\end{theorem}
\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:transport} to $\delta$, which has uniform fibres of size $\kappa^2$. In both rows, $n_{L_G}=\kappa^2n_{L_H}\circ\delta$ and $|\Omega_G|=\kappa^2|\Omega_H|$.
\emph{Pair row:} $n_P=|C|=n_{P_H}\circ\delta$, and inside a pair cell the label depends only on the coin, so $n_{L,P}=n_{L_H,P_H}\circ\delta$.
\emph{Product row:} $n_N=|G||C|=\kappa|H||C|$ while $n_{N_H}=|H||C|$. By Lemma~\ref{lem:factor}, $n_{L,N}=\kappa\,n_{L_H,N_H}\circ\delta$. The ratio upstairs equals
\[
\frac{\kappa^2|\Omega_H|\cdot\kappa n_{L_H,N_H}}{\kappa|H||C|\cdot\kappa^2n_{L_H}}=\frac{|\Omega_H|\,n_{L_H,N_H}}{|H||C|\,n_{L_H}},
\]
which is the ratio downstairs.
\end{proof}

\begin{corollary}[Conductor universality]\label{cor:universal}
The population hint value depends only on $(H,C,\ell)$, and not on the conductor group.
\end{corollary}

\section{Residuals and the pool-floor exception}\label{sec:pool}

\begin{proposition}\label{prop:residual}
$\Hint(L,P,N)=H(L\mid N)-H(L\mid P)$.
\end{proposition}

\begin{lemma}\label{lem:zero}
$H(L\mid P)\ge0$. If $L=\lambda\circ P$, or if $P$ is injective, then $H(L\mid P)=0$.
\end{lemma}

\begin{theorem}[Pool-floor theorem]\label{thm:pool}
For every battery:
\begin{enumerate}
\item $\Hint\le H(L\mid N)$;
\item if $L$ is a function of $P$, then $\Hint=H(L\mid N)$;
\item if $P$ is injective (at most one sample per residue-pair class), then $\Hint=H(L\mid N)$ for every label, and the excess over the population value is exactly the population residual.
\end{enumerate}
\end{theorem}

\begin{remark}
In a thin pool the pair residue partially identifies the prime, and the prime determines its type. This leakage lowers the empirical residual, so it can only raise $\Hint$, and by at most the residual. Abelian labels are residue functions, so their residual is $0$ at every size and nothing leaks. For $S_3$ the reading $0.7423$ at $k=10$ satisfies $\tfrac12<0.7423<\log_23-\tfrac5{18}\approx1.3072$, as the diagnosis requires. Theorem~\ref{thm:size} covers uniform replication; unbalanced pools are controlled by the inequality in part~1.
\end{remark}

\section{The which-factor wall}\label{sec:wall}

Let $\sigma$ be an involution of $\Omega$ (the factor swap). An \emph{orientation bit} satisfies $O\circ\sigma=\neg O$, and a \emph{symmetric view} satisfies $V\circ\sigma=V$.

\begin{lemma}\label{lem:half}
For every $\sigma$-invariant predicate $Q$ and $b\in\{0,1\}$, $2\#\{Q,\ O=b\}=\#\{Q\}$.
\end{lemma}
\begin{proof}
$\sigma$ maps $\{Q,O=b\}$ bijectively onto $\{Q,O=\neg b\}$.
\end{proof}

\begin{theorem}[Which-factor wall]\label{thm:wall}
$I(O;V)=0$ for every orientation bit $O$ and every symmetric view $V$.
\end{theorem}
\begin{proof}
Lemma~\ref{lem:half} gives $2n_O=|\Omega|$ and $2n_{V,O}=n_V$. So every pointwise ratio is $1$; apply Proposition~\ref{prop:pointwise}.
\end{proof}

\begin{proposition}[The naive instrument fails]
On $\{(2,3),(3,2)\}$ with $O=[p<q]$: $I(O;p\bmod5)=1$, while $I\bigl(O;(pq\bmod5,\min(p,q)\bmod5,\max(p,q)\bmod5)\bigr)=0$.
\end{proposition}
\begin{proof}
The residue $p\bmod5$ separates the two points, so it determines the fair bit $O$. The second view is symmetric, so Theorem~\ref{thm:wall} applies.
\end{proof}

\section{Exact plateaus}\label{sec:plateaus}

\subsection{$S_3$ at conductor $31$}
The cubic $x^3+x+1$ has discriminant $-31$. The dial is the Legendre symbol mod $31$, which is surjective because $3$ is a non-residue. A non-residue prime has exactly one root (Frobenius is a transposition). A residue prime has $3$ roots with probability $\tfrac13$ and $0$ roots with probability $\tfrac23$. This rule was confirmed for every prime below $200$. The dial box has $36$ points. Writing $\log=\log_2$:
\begin{itemize}
\item given $P=(-,-)$: entropy $0$; given $P=(\pm,\mp)$: $\log3-\tfrac23$; given $P=(+,+)$: $2\log3-\tfrac{16}9$; hence $H(L\mid P)=\log3-\tfrac79$;
\item given $N=-1$: $\log3-\tfrac23$; given $N=+1$: $\log3+\tfrac19$; hence $H(L\mid N)=\log3-\tfrac5{18}$.
\end{itemize}

\begin{theorem}[$S_3$ plateau]
The $S_3$ battery has $\Hint=\tfrac12$, residual $\log_23-\tfrac79>0$ and ceiling $\log_23-\tfrac5{18}$. The value $\tfrac12$ holds at every conductor with a surjective quadratic dial carrying the same label, and after any replication.
\end{theorem}
\begin{proof}
Theorem~\ref{thm:lift} reduces the $8100$-point residue space to the box, where $I(L;P)=\tfrac32$ and $I(L;N)=1$. Then apply Corollary~\ref{cor:universal} and Theorem~\ref{thm:size}.
\end{proof}

\subsection{$D_4$ at conductor $8$}
The root count of $x^4-2$ mod an odd prime $p$ is $4$ or $0$ (by a coin) if $p\equiv1\pmod 8$, $2$ if $p\equiv7$, and $0$ if $p\equiv3,5$. This was confirmed for every odd prime below $200$.

\begin{theorem}[$D_4$ plateau]
$\Hint_{D_4}=\tfrac32-\tfrac9{32}\log_23\approx1.05423$, with residual $\tfrac{15}{32}$.
\end{theorem}
\begin{proof}[Proof sketch]
On the $64$-point box, $I(L;P)=\tfrac92-\tfrac54\log_25$ and $I(L;N)=3-\tfrac54\log_25+\tfrac9{32}\log_23$.
\end{proof}

Cycle-type labels would give $1.1936$, which is incompatible with the data. The labels are therefore root counts.

\subsection{Abelian batteries}
For the degree-$n$ subfield of $\Q(\zeta_f)$ fixed by $\{\pm1\}$, with $(n,f)=(3,7)$ or $(5,11)$, a prime splits iff $p\equiv\pm1\pmod f$. The label is a function of $P$, so $\Hint=H(L\mid N)$.

\begin{theorem}[Abelian plateaus]
$\Hint_{C_3}=\log_23-\tfrac23\approx0.91830$ and $\Hint_{C_5}=\log_25-\tfrac{12}{25}\log_23-\tfrac{16}{25}\approx0.92115$, with residual exactly $0$.
\end{theorem}
\begin{proof}[Proof sketch for $C_3$]
Whatever $N\bmod7$ is, the conditional label law is a $\tfrac13$-$\tfrac23$ coin, so $H(L\mid N)=h(\tfrac13)=\log_23-\tfrac23$.
\end{proof}

