from collections import Counter
from math import gcd, log2
from typing import Callable, Hashable, List, Tuple


def H(keys: List[Hashable]) -> float:
    n = len(keys)
    return -sum(c / n * log2(c / n) for c in Counter(keys).values())


def hint_on(points: List[Tuple]) -> float:
    """points: (label, pair_view, product_view) triples under the uniform law."""
    L = [p[0] for p in points]
    hLP = H([(p[0], p[1]) for p in points]) - H([p[1] for p in points])
    hLN = H([(p[0], p[2]) for p in points]) - H([p[2] for p in points])
    return hLN - hLP


def dial_box(H_elems: List, mul: Callable, coins: List, label: Callable) -> List[Tuple]:
    """Enumerate the dial box (H x H) x C^2 instead of the residue space (G x G) x C^2."""
    return [(label(h1, h2, c1, c2), (h1, h2), mul(h1, h2))
            for h1 in H_elems for h2 in H_elems for c1 in coins for c2 in coins]


def residue_space(m: int, psi: Callable[[int], Hashable], coins: List, label: Callable) -> List[Tuple]:
    U = [a for a in range(1, m) if gcd(a, m) == 1]
    return [(label(psi(a), psi(b), c1, c2), (a, b), a * b % m)
            for a in U for b in U for c1 in coins for c2 in coins]


if __name__ == "__main__":
    roots = lambda s, c: 1 if s == -1 else (3 if c == 0 else 0)
    lab = lambda s, t, c1, c2: tuple(sorted((roots(s, c1), roots(t, c2))))
    print("dial box (36 points):", hint_on(dial_box([1, -1], lambda a, b: a * b, [0, 1, 2], lab)))
    for m in (7, 31, 103):
        leg = lambda a, m=m: 1 if pow(a, (m - 1) // 2, m) == 1 else -1
        pts = residue_space(m, leg, [0, 1, 2], lab)
        print(f"residue space mod {m} ({len(pts)} points):", round(hint_on(pts), 12))
